        "bearing-off-doublets" => true,
        "win-condition" => true,
        "game-value" => true,
        "agreed-backgammon-multiple" => Hooked("AgreedBackgammonMultiple", typeof(global::HoyleBackgammon.Requests.AgreedBackgammonMultipleRequest)),
        "stake-multiplier" => true,
        "hit-pays-single-stake" => true,
        "next-game-opening" => true,
        "rubber-scoring" => true,
        "die-faces" => true,
        "doubling-cube" => Hooked("DoublingCube", typeof(global::HoyleBackgammon.Requests.DoublingCubeRequest)),
        "strategy-advice" => Hooked("StrategyAdvice", typeof(global::HoyleBackgammon.Requests.StrategyAdviceRequest)),
        _ => false,
    };

    private static bool Hooked(string name, Type request) =>
        typeof(Handlers).GetMethod(name, BindingFlags.NonPublic | BindingFlags.Static, [request, typeof(Resolution<object>).MakeByRefType()]) is not null;
}
